export const stores = { sessions: cms.sessions, jobs: cms.jobs(), notifications: cms.notifications() };

import { createRomeDB, MemoryPendingWriteStore } from '@cossackframework/romedb';
import { contentModule, createCMS, userPrincipal } from '@cossackframework/cms/server';

const db = createRomeDB({ url: 'http://127.0.0.1:4321', token: 'local-service-token', pending: new MemoryPendingWriteStore() });
const cms = createCMS({ db, modules: [contentModule] });
const editor = userPrincipal('editor-1', ['editor'], ['cms:dashboard', 'cms/*']);

export async function launchTomorrow(): Promise<string> {
    const tomorrow = Date.now() + 24 * 60 * 60 * 1000;
    const post = await cms.resource('cms/posts').create({ title: 'Launch day', status: 'published', publishedAt: tomorrow }, { principal: editor });
    // post.status is 'scheduled'; maintenance publishes it tomorrow.
    const link = await cms.createPreviewLink('cms/posts', post.id, editor);
    await cms.webhooks.save({ name: 'Rebuild', url: 'https://api.example.com/hooks/build', events: ['entry.published'], collections: ['posts'] });
    return `/preview/posts/${post.id}?token=${link.token}`;
}

export async function maintenance(): Promise<void> {
    await cms.publishDue();
    await cms.outbox.dispatch();
    await cms.webhooks.dispatch();
}

import { createRomeDB, MemoryPendingWriteStore } from '@cossackframework/romedb';
import { createHookRegistry } from '@cossackframework/core/hooks';
import { ANONYMOUS, contentModule, createCMS, formsModule, formSubmitted, formValidate, userPrincipal, type Block } from '@cossackframework/cms/server';

// A plugin's or the application's own rules, as Gravity Forms' hooks.
const hooks = createHookRegistry();
hooks.addFilter(formValidate, (errors, { input }) => typeof input.values.email === 'string' && input.values.email.endsWith('@example.org')
    ? { ...errors, email: 'Use your work address.' } : errors, { plugin: 'app' });
hooks.addAction(formSubmitted, async event => {
    // Send the lead to a CRM, keyed by event.eventId: deliveries can repeat.
    console.log(event.form.slug, event.submission.values);
}, { plugin: 'app' });

const db = createRomeDB({ url: 'http://127.0.0.1:4321', token: 'local-service-token', pending: new MemoryPendingWriteStore() });
const cms = createCMS({
    db, modules: [contentModule, formsModule], hooks, mailFrom: 'site@example.com',
    mail: { async send(message) { console.log('mail to', message.to, message.subject); } },
});
const editor = userPrincipal('editor-1', ['editor'], ['cms:dashboard', 'cms:submissions', 'cms/*']);

const body: Block[] = [
    { id: 'n', type: 'form/text', data: { label: 'Your name', required: true } },
    { id: 'e', type: 'form/email', data: { label: 'Email', name: 'email', required: true } },
    { id: 'c', type: 'form/checkbox', data: { label: 'Call me', name: 'callMe' } },
    { id: 'p', type: 'form/phone', data: { label: 'Phone', name: 'phone', required: true }, when: { rules: [{ field: 'callMe', op: 'is', value: 'true' }] } },
];

export async function contactForm(): Promise<string> {
    await cms.resource('cms/forms').create({
        title: 'Contact', body,
        notifications: { rules: [{ id: 'admin', label: 'Admin', to: '{admin_email}', subject: 'New message from {field:yourName}', body: '{all_fields}' }] },
    }, { principal: editor });
    const { submission } = await cms.forms.submit('contact', { yourName: 'Ada', email: 'ada@example.com' }, { principal: ANONYMOUS, ip: '203.0.113.7', page: '/contact' });
    await cms.outbox.dispatch();
    const form = await cms.forms.get('contact');
    let csv = '';
    if (form) for await (const chunk of cms.forms.csv(form, {}, editor)) csv += chunk;
    return `${submission.id}\n${csv}`;
}

import { createRomeDB, MemoryPendingWriteStore } from '@cossackframework/romedb';
import { contentModule, createCMS, derivedFields, fieldGroupDeclarations, fieldGroupProblems, fieldVisibility, userPrincipal, type Block, type FieldGroup } from '@cossackframework/cms/server';

const fieldBlock = (id: string, kind: string, data: { [key: string]: unknown }, extra: Partial<Block> = {}): Block => ({ id, type: `field/${kind}`, data: { label: id, ...data }, ...extra });

// Specifications: a repeater with an indexed name, a kind, and a URL shown for links.
const specifications: FieldGroup = {
    id: 'specifications', title: 'Specifications', targets: [{ kind: 'collection', name: 'products' }],
    blocks: [
        { id: 'h', type: 'core/heading', data: { text: 'Specifications' } },
        fieldBlock('specs', 'repeater', { name: 'specs', label: 'Specifications', max: 20, summary: 'name' }, { children: [
            fieldBlock('name', 'text', { name: 'name', label: 'Name', required: true, index: true, search: true }),
            fieldBlock('kind', 'choice', { name: 'kind', label: 'Kind', choices: ['text', 'link'] }),
            fieldBlock('url', 'text', { name: 'url', label: 'URL' }, { when: { rules: [{ field: 'kind', op: 'is', value: 'link' }] } }),
        ] }),
    ],
};

const db = createRomeDB({ url: 'http://127.0.0.1:4321', token: 'token', pending: new MemoryPendingWriteStore() });
const cms = createCMS({ db, modules: [contentModule] });
const admin = userPrincipal('admin-1', ['admin'], ['*']);

async function main(): Promise<void> {
    await cms.ready();
    // Pure checks before saving: the tree, the compiled fields, the derived lists.
    const { problems, fields } = fieldGroupProblems(specifications, cms.blockTypes, ['title', 'status']);
    if (problems.length) throw new Error(problems.join(' '));
    console.log(Object.keys(fields), Object.keys(derivedFields(fields)));             // ['specs'], ['specs__name']
    console.log(fieldGroupDeclarations(specifications.blocks, cms.blockTypes).specs?.kind); // 'rows'
    const hidden = fieldVisibility(specifications.blocks, cms.blockTypes, { specs: [{ _id: 'r1', kind: 'text', url: 'gone' }] });
    console.log([...hidden.hidden], hidden.values);                                   // ['specs=r1/url'], { specs: [{ _id: 'r1', kind: 'text' }] }

    await cms.saveFieldGroup(specifications, admin);
    const products = cms.resource('cms/products');
    const skates = await products.create({ title: 'Rocket skates', specs: [{ name: 'Weight', kind: 'text' }, { name: 'Site', kind: 'link', url: 'https://example.com' }] }, { principal: admin });
    console.log((skates.specs as { _id: string }[]).map(row => row._id));
    const found = await products.list({ where: { 'specs.name': { contains: 'Weight' } } }, { principal: admin });
    console.log(found.records.map(record => record.title));                           // ['Rocket skates']
    await cms.taxonomies.create('categories', { name: 'Skates', meta: {} }, { principal: admin });
}

void main();
